-- Forecasts come from the stored coefficients; the 80% range is ±1.2816 × residual standard error, floored at 0 days.
insert into public.forecasts (project_id, model_run_id, predicted_days, low_days, high_days)
select p.id, m.id, d.days,
       greatest(0, round(d.days - 1.2816 * m.residual_std_error::numeric, 1)),
       round(d.days + 1.2816 * m.residual_std_error::numeric, 1)
from public.projects p
join public.model_runs m on m.name = 'weekday-ols-v0'
cross join lateral (select public.predict_days(p.id, m.name) as days) d;

commit;
